// Single source of truth for built-in AI providers (catalog order, fallback
// order, runtime caller tables, defaults, UI labels, status pages, and fields).
// After editing this table, run `node scripts/sync-ai-providers.mjs --write`
// to regenerate every `@generated:ai-providers` region across runtime files.

function deepFreeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const child of Object.values(value)) deepFreeze(child);
  }
  return value;
}

